"""AQS-CTL-003 safety instrumented functions and cause and effect (X-CTL-03, A-M-197). Sources: the HAZOP trip actions
(docs-authority/hazop_actions.csv), every high-level switch of AQS-CTL-001 (feed trip), and the gas and flame detection of AQS-SAF-005.
SIL target from a calibrated risk graph (IEC61511_2016 part 3 annex D form): consequence class from the hazard (fire or explosion with
people present = SIL 2; equipment damage or toxic release inside a bund = SIL 1; overfill to a bund = no SIL, basic control alarm).
Sensors 1oo2 for SIL 2, 1oo1 for SIL 1; logic on a safety PLC separate from the basic control PLCs (AQS-CTL-002); final element de-energise
to trip. Closes the HAZOP trip actions. Run after _hazop.py: python3 docs-authority/_sif.py"""
import csv, json, os, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
for k in ('IEC61511_2016', 'NFPA2_2023', 'NFPA69_2019'): cite(k)
A = list(csv.DictReader(open('docs-authority/hazop_actions.csv'))); I = list(csv.DictReader(open('docs-authority/inventory/INSTRUMENT_INDEX.csv')))
tags = collections.defaultdict(dict)
for r in I:
    if int(r['tag'].split('-')[-1]) < 90: tags[r['unit']].setdefault(r['tag'].split('-')[-2], r['tag'])
ALL = {r['tag'] for r in I}
S = []
def sif(unit, init, cause, effect, final, sil, src):
    S.append(dict(id=f'SIF-{len(S)+1:03d}', unit=unit, initiator=init, cause=cause, effect=effect, final_element=final, SIL=sil, voting='1oo2' if sil == 2 else '1oo1', source=src))
for a in A:
    if a['closing_task'] != 'X-CTL-03': continue
    u = a['node']; t = tags[u]
    if a['action'].startswith('independent high-temperature'):
        s = sif(u, f"{u}-TE-90 (independent element; not {t.get('TE', 'the control TE')})", 'temperature high-high', 'heater supply off', 'heater contactor, de-energise', 2 if any(k in u for k in ('PYRO', 'AFTERBURN', 'HCL', 'MELT')) else 1, a['action_id'])
    elif a['action'].startswith('PT low-low'):
        sif(u, t.get('PT', f'{u}-PT-01') + ' + second PT', 'pressure low-low (leak)', 'close bank isolation valves, stop compressor, alarm', 'bank outlet ESD valves (one per half), fail closed', 2, a['action_id'])
    else:
        sif(u, t.get('FT', t.get('LT', u)), 'flow or level low-low', 'pump stop', 'pump starter, de-energise', 1, a['action_id'])
for u, t in sorted(tags.items()):
    if 'LSH' in t: sif(u, t['LSH'], 'level high-high', 'close feed valve / stop feed pump', 'feed valve fail closed', 0, 'AQS-CTL-001 LSH')
sif('CRYO_H2 area', 'H2 gas detectors 2oo3', 'H2 at 25 % LFL', 'trip H2O_ELYZ and its rectifier, close H2 bank ESD valves, purge ventilation to high', 'rectifier breaker, ESD valves', 2, 'AQS-SAF-005, NFPA 2, NFPA 69')
sif('CRYO_H2 / CRYO_O2', 'UV/IR flame detectors 2oo2', 'flame at a receiver', 'water spray on, depressuring valves open (API 521 5.20)', 'deluge valve, depressuring valves fail open', 2, 'AQS-SAF-005')
sif('CRYO_O2 area', 'O2 detectors 2oo3', 'O2 above 23.5 %', 'close O2 bank and IA-ELY-O2 isolation, ventilation to high', 'ESD valves fail closed', 1, 'AQS-SAF-005')
sif('ZNBR2', 'H2 detectors in the headspace 1oo2', 'H2 at 25 % LFL in the purge', 'stop charging, purge fan to high', 'charge contactor', 1, 'NFPA 855, NFPA 69, ess_tf purge basis')
bad = [s['initiator'].split()[0] for s in S if s['initiator'].split()[0].count('-') >= 2 and s['initiator'].split()[0] not in ALL and 'TE-90' not in s['initiator']]
assert not bad, f'SIF initiators missing from AQS-CTL-001: {bad[:5]}'
miss90 = [s['unit'] for s in S if 'TE-90' in s['initiator'] and f"{s['unit']}-TE-90" not in ALL]
if miss90: print('note: TE-90 not yet in index (first pass):', len(miss90))
closed = {s['source']: s['id'] for s in S}
for a in A:
    if a['action_id'] in closed: a['status'] = f"closed by {closed[a['action_id']]} (AQS-CTL-003)"
with open('docs-authority/hazop_actions.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(A[0])); w.writeheader(); w.writerows(A)
with open('docs-authority/sif_list.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(S[0])); w.writeheader(); w.writerows(S)
K = collections.Counter(s['SIL'] for s in S); op = sum(1 for a in A if a['status'].startswith('open'))   # includes 'open - tracked' rows (AQS-SAF-008)
md = ['# Safety instrumented functions and cause and effect', '', 'Document number: AQS-CTL-003', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-CTL-03. Generated by `docs-authority/_sif.py` from AQS-SAF-001 and AQS-CTL-001. IEC61511_2016. Study. A-M-197.', '',
      f"{len(S)} functions: SIL 2 {K[2]}, SIL 1 {K[1]}, no SIL (basic control trip) {K[0]}. HAZOP actions open after the SIF pass: {op} (tracked in AQS-SAF-008 with owner tasks).", '',
      'Logic solver: a safety PLC with its own I/O, separate from the basic control PLCs; de-energise to trip; bypasses only under permit with a timer. SIL 2 loops use 1oo2 sensors; proof-test interval 1 year (AQS-OPS-002).', '',
      '| SIF | Unit | Initiator | Cause | Effect | Final element | SIL | Voting | Source |', '|---|---|---|---|---|---|---|---|---|']
md += [f"| {s['id']} | {s['unit']} | {s['initiator']} | {s['cause']} | {s['effect']} | {s['final_element']} | {s['SIL'] or '-'} | {s['voting']} | {s['source']} |" for s in S]
open('docs-authority/CAUSE_EFFECT.md', 'w').write('\n'.join(md) + '\n'); print(len(S), dict(K), 'open', op)
